// Flow pack — edge-mask tile grids: one data model, two games. Netwalk (rotate
// tiles to connect a spanning tree to the server) and Pipe Mania (place pipes
// from a forced queue while fluid advances on the game's clock). A tile is a
// 4-bit edge mask; connectivity is a live flood over matching stubs. Its own
// artifact, not in webgpu.js.

export interface XY { x: number; y: number }

// Edge bits: 1=up, 2=right, 4=down, 8=left.
export const UP = 1, RIGHT = 2, DOWN = 4, LEFT = 8;
const OPP: Record<number, number> = { [UP]: DOWN, [RIGHT]: LEFT, [DOWN]: UP, [LEFT]: RIGHT };
const DIRS: [number, number, number][] = [[UP, 0, -1], [RIGHT, 1, 0], [DOWN, 0, 1], [LEFT, -1, 0]];

export interface Tile {
  /** 4-bit edge mask of connection stubs. */
  mask: number;
  kind?: 'source' | 'drain' | 'normal';
  /** Netwalk: locked against accidental rotation. */
  locked?: boolean;
}

class Rng {
  private s: number;
  constructor(seed: number) { this.s = (seed >>> 0) || 0x9e3779b9; }
  next(): number { let x = this.s; x ^= x << 13; x ^= x >>> 17; x ^= x << 5; this.s = x >>> 0; return this.s; }
  int(n: number): number { return n <= 0 ? 0 : this.next() % n; }
  shuffle<T>(a: T[]): T[] { for (let i = a.length - 1; i > 0; i--) { const j = this.int(i + 1); [a[i], a[j]] = [a[j], a[i]]; } return a; }
}

export interface FlowConfig {
  cols: number;
  rows: number;
  seed?: number;
  /** Toroidal wrap for adjacency. Default false. */
  wrap?: boolean;
}

function rotateMask(mask: number, steps: number): number {
  // rotate clockwise: up→right→down→left. Bit layout up=1,right=2,down=4,left=8.
  let m = mask & 0xf;
  const s = ((steps % 4) + 4) % 4;
  for (let n = 0; n < s; n++) m = ((m << 1) | (m >> 3)) & 0xf;
  return m;
}

export function createFlowGrid(cfg: FlowConfig): FlowGrid {
  return new FlowGrid(cfg);
}

export class FlowGrid {
  readonly cols: number;
  readonly rows: number;
  private wrap: boolean;
  private tiles: Tile[];
  private server: XY | null = null;
  private rng: Rng;

  // Pipe Mania state.
  queue: number[] = [];   // masks, no rotation
  private flowHead: { at: XY; from: number } | null = null;
  private filled: boolean[];        // a cell's pipe has fluid
  filledDist = 0;
  private solvedMask: number[] | null = null; // Netwalk solution, stored at gen time

  constructor(cfg: FlowConfig) {
    this.cols = cfg.cols;
    this.rows = cfg.rows;
    this.wrap = cfg.wrap ?? false;
    this.rng = new Rng(cfg.seed ?? 1);
    this.tiles = new Array(cfg.cols * cfg.rows).fill(null).map(() => ({ mask: 0, kind: 'normal' as const }));
    this.filled = new Array(cfg.cols * cfg.rows).fill(false);
  }

  private idx(x: number, y: number): number { return y * this.cols + x; }
  private inBounds(x: number, y: number): boolean { return x >= 0 && y >= 0 && x < this.cols && y < this.rows; }
  private neighbour(x: number, y: number, dx: number, dy: number): XY | null {
    let nx = x + dx; let ny = y + dy;
    if (this.wrap) { nx = ((nx % this.cols) + this.cols) % this.cols; ny = ((ny % this.rows) + this.rows) % this.rows; }
    return this.inBounds(nx, ny) ? { x: nx, y: ny } : null;
  }

  tile(x: number, y: number): Tile { return this.tiles[this.idx(x, y)]; }
  setTile(x: number, y: number, t: Tile): void { this.tiles[this.idx(x, y)] = { ...t }; }
  get serverPos(): XY | null { return this.server; }

  /** Rotate a tile (Netwalk). +1 = clockwise. Ignored if locked. */
  rotate(x: number, y: number, steps = 1): void {
    const t = this.tiles[this.idx(x, y)];
    if (t.locked) return;
    t.mask = rotateMask(t.mask, steps);
  }

  /** Toggle a tile's lock (misclick guard). */
  lock(x: number, y: number, on: boolean): void { this.tiles[this.idx(x, y)].locked = on; }

  /** Cells connected to the server via mutually-matching stubs (the lit network). */
  connectivity(): { lit: boolean[]; litCount: number } {
    const lit = new Array(this.cols * this.rows).fill(false);
    if (!this.server) return { lit, litCount: 0 };
    const start = this.idx(this.server.x, this.server.y);
    lit[start] = true;
    const stack: XY[] = [this.server];
    let count = 1;
    while (stack.length) {
      const p = stack.pop()!;
      const t = this.tiles[this.idx(p.x, p.y)];
      for (const [bit, dx, dy] of DIRS) {
        if (!(t.mask & bit)) continue;
        const nb = this.neighbour(p.x, p.y, dx, dy);
        if (!nb) continue;
        const nt = this.tiles[this.idx(nb.x, nb.y)];
        if (!(nt.mask & OPP[bit])) continue; // both sides must have a stub
        const ni = this.idx(nb.x, nb.y);
        if (!lit[ni]) { lit[ni] = true; count++; stack.push(nb); }
      }
    }
    return { lit, litCount: count };
  }

  /** Solved (Netwalk) when every tile with any stub is lit and no dangling stubs
   * point at walls or unmatched neighbours. */
  get solved(): boolean {
    const { lit } = this.connectivity();
    for (let y = 0; y < this.rows; y++) {
      for (let x = 0; x < this.cols; x++) {
        const t = this.tiles[this.idx(x, y)];
        if (t.mask === 0) continue;
        if (!lit[this.idx(x, y)]) return false;
        // no stub may point off-board or into a stub-less neighbour
        for (const [bit, dx, dy] of DIRS) {
          if (!(t.mask & bit)) continue;
          const nb = this.neighbour(x, y, dx, dy);
          if (!nb) return false;
          if (!(this.tiles[this.idx(nb.x, nb.y)].mask & OPP[bit])) return false;
        }
      }
    }
    return true;
  }

  /** Generate a solvable Netwalk: carve a random spanning tree from the server,
   * set edge masks, then scramble rotations. Always solvable. */
  generateNet(): void {
    const n = this.cols * this.rows;
    this.tiles = new Array(n).fill(null).map(() => ({ mask: 0, kind: 'normal' as const }));
    this.server = { x: this.rng.int(this.cols), y: this.rng.int(this.rows) };
    this.tiles[this.idx(this.server.x, this.server.y)].kind = 'source';
    // Randomized DFS spanning tree.
    const visited = new Array(n).fill(false);
    const startI = this.idx(this.server.x, this.server.y);
    visited[startI] = true;
    const stack: XY[] = [this.server];
    while (stack.length) {
      const p = stack[stack.length - 1];
      const options: [number, number, number, XY][] = [];
      for (const [bit, dx, dy] of DIRS) {
        const nb = this.neighbour(p.x, p.y, dx, dy);
        if (nb && !visited[this.idx(nb.x, nb.y)]) options.push([bit, dx, dy, nb]);
      }
      if (options.length === 0) { stack.pop(); continue; }
      const [bit, , , nb] = options[this.rng.int(options.length)];
      // add the edge both ways
      this.tiles[this.idx(p.x, p.y)].mask |= bit;
      this.tiles[this.idx(nb.x, nb.y)].mask |= OPP[bit];
      visited[this.idx(nb.x, nb.y)] = true;
      stack.push(nb);
    }
    // Record the solved orientation, THEN scramble each tile a random amount.
    this.solvedMask = this.tiles.map((t) => t.mask);
    for (let i = 0; i < n; i++) this.tiles[i].mask = rotateMask(this.tiles[i].mask, this.rng.int(4));
  }

  /** Rotation steps per cell that solve the generated Netwalk (autoplay/hints).
   * Uses the solved orientation recorded at generation time. Null if not generated. */
  solveNet(): number[][] | null {
    if (!this.solvedMask) return null;
    const out: number[][] = [];
    for (let y = 0; y < this.rows; y++) {
      out.push([]);
      for (let x = 0; x < this.cols; x++) {
        const i = this.idx(x, y);
        const cur = this.tiles[i].mask;
        const target = this.solvedMask[i];
        let steps = 0;
        while (steps < 4 && rotateMask(cur, steps) !== target) steps++;
        out[y].push(steps % 4);
      }
    }
    return out;
  }

  // ---- Pipe Mania -----------------------------------------------------------

  /** Seed a Pipe Mania game: a forced queue of pipe masks and a start tile. */
  startPipes(queue: number[], start: XY, fromDir: number): void {
    this.queue = queue.slice();
    this.tiles = new Array(this.cols * this.rows).fill(null).map(() => ({ mask: 0, kind: 'normal' as const }));
    this.filled = new Array(this.cols * this.rows).fill(false);
    // start tile is a stub pointing in fromDir's opposite (fluid enters from fromDir)
    this.tiles[this.idx(start.x, start.y)] = { mask: fromDir, kind: 'source' };
    this.flowHead = { at: start, from: OPP[fromDir] };
    this.filledDist = 0;
  }

  /** Place the next queued pipe at an empty cell. Returns false if occupied/filled. */
  placePipe(x: number, y: number): boolean {
    const i = this.idx(x, y);
    if (this.filled[i] || this.tiles[i].mask !== 0 || this.tiles[i].kind === 'source') return false;
    const mask = this.queue.shift();
    if (mask === undefined) return false;
    this.tiles[i] = { mask, kind: 'normal' };
    this.queue.push(0); // keep the queue topped (game supplies real masks; 0 = placeholder)
    return true;
  }

  /** Advance the fluid one pipe segment. Returns the outcome. */
  advanceFlow(): { entered: XY | null; spilled: boolean; dist: number } {
    if (!this.flowHead) return { entered: null, spilled: false, dist: this.filledDist };
    const { at, from } = this.flowHead;
    const t = this.tiles[this.idx(at.x, at.y)];
    this.filled[this.idx(at.x, at.y)] = true;
    this.filledDist++;
    // the pipe must have a stub on `from` and an outgoing stub elsewhere
    if (!(t.mask & from) && t.kind !== 'source') return { entered: at, spilled: true, dist: this.filledDist };
    // pick the exit (the other stub)
    let exitBit = 0;
    for (const [bit] of DIRS) if ((t.mask & bit) && bit !== from) { exitBit = bit; break; }
    if (exitBit === 0) return { entered: at, spilled: true, dist: this.filledDist };
    const dir = DIRS.find(([b]) => b === exitBit)!;
    const nb = this.neighbour(at.x, at.y, dir[1], dir[2]);
    if (!nb) return { entered: at, spilled: true, dist: this.filledDist };
    const nt = this.tiles[this.idx(nb.x, nb.y)];
    if (nt.mask === 0 || !(nt.mask & OPP[exitBit])) return { entered: nb, spilled: true, dist: this.filledDist };
    this.flowHead = { at: nb, from: OPP[exitBit] };
    return { entered: nb, spilled: false, dist: this.filledDist };
  }

  isFilled(x: number, y: number): boolean { return this.filled[this.idx(x, y)]; }

  debugMasks(): string {
    const rows: string[] = [];
    for (let y = 0; y < this.rows; y++) {
      let r = '';
      for (let x = 0; x < this.cols; x++) r += this.tiles[this.idx(x, y)].mask.toString(16);
      rows.push(r);
    }
    return rows.join('\n');
  }
}

function popcount(n: number): number { let c = 0; while (n) { c += n & 1; n >>= 1; } return c; }
